#include "kernel.h"
#include <hls_math.h>
#include <stdint.h>

// ---------------------------------------------------------------------------
// Internal double-precision helpers (HLS synthesises these as DSP chains)
// ---------------------------------------------------------------------------

static double d_sqrt(double x) { return hls::sqrt(x); }
static double d_atan2(double y, double x) { return hls::atan2(y, x); }
static double d_cos(double x)  { return hls::cos(x);  }
static double d_sin(double x)  { return hls::sin(x);  }

// ---------------------------------------------------------------------------
// kernel_top
// Implements complex Hermitian Jacobi eigenvalue decomposition.
// For a Hermitian matrix A, find unitary V such that V^H * A * V = D (diagonal).
// ---------------------------------------------------------------------------
void kernel_top(
    acm_t  A_re[N][N],
    acm_t  A_im[N][N],
    iter_t max_iter,
    eval_t eigenvalues_re[N],
    eval_t eigenvalues_im[N],
    evec_t eigenvectors_re[N][N],
    evec_t eigenvectors_im[N][N],
    iter_t &ite,
    uint32_t &clock_cycles)
{
#pragma HLS INTERFACE ap_ctrl_hs port=return
#pragma HLS INLINE off

    // ------------------------------------------------------------------
    // Working arrays in double precision
    // ------------------------------------------------------------------
    double AR[N][N], AI[N][N];   // matrix A (real/imag)
    double VR[N][N], VI[N][N];   // eigenvector accumulator V

    // Initialise A from inputs, V = identity
    INIT_ROW: for (int i = 0; i < N; i++) {
        INIT_COL: for (int j = 0; j < N; j++) {
            AR[i][j] = (double)A_re[i][j];
            AI[i][j] = (double)A_im[i][j];
            VR[i][j] = (i == j) ? 1.0 : 0.0;
            VI[i][j] = 0.0;
        }
    }

    // Enforce Hermitian symmetry on input (A = (A + A^H)/2)
    for (int i = 0; i < N; i++) {
        for (int j = i+1; j < N; j++) {
            double re = 0.5*(AR[i][j] + AR[j][i]);
            double im = 0.5*(AI[i][j] - AI[j][i]);
            AR[i][j] = re; AI[i][j] =  im;
            AR[j][i] = re; AI[j][i] = -im;
        }
        // diagonal must be real for Hermitian
        AI[i][i] = 0.0;
    }

    clock_cycles = 0;
    uint32_t local_cycles = 0;

    int last_z = 0;

    // ------------------------------------------------------------------
    // Main Jacobi loop
    // Complex Hermitian Jacobi:
    //   For pivot (p,q), the unitary rotation is:
    //   U[p,p] = c,              U[p,q] = s * exp(-i*phi)
    //   U[q,p] = -s * exp(i*phi), U[q,q] = c
    //   where c = cos(theta), s = sin(theta)
    //   phi  = angle(a_pq)
    //   theta: chosen to zero out a_pq after similarity transform
    //   The similarity A -> U^H * A * U
    // ------------------------------------------------------------------
    JACOBI_OUTER: for (int z = 0; z < (int)max_iter; z++) {
#pragma HLS LOOP_TRIPCOUNT min=1 max=1000 avg=100

        // ---- find largest off-diagonal element -------------------------
        double off_diag_max = 0.0;
        int p = 0, q = 1;

        FIND_P: for (int i = 0; i < N; i++) {
            FIND_Q: for (int j = i + 1; j < N; j++) {
                double re = AR[i][j], im = AI[i][j];
                double mag2 = re*re + im*im;
                local_cycles++;
                if (mag2 > off_diag_max) {
                    off_diag_max = mag2;
                    p = i;
                    q = j;
                }
            }
        }
        local_cycles++;

        // ---- convergence check -----------------------------------------
        if (off_diag_max < 1e-20) {
            last_z = z;
            break;
        }
        last_z = z;

        // ---- compute rotation parameters -----------------------------------
        double app_r = AR[p][p];  // diagonal elements are real
        double aqq_r = AR[q][q];
        double apq_r = AR[p][q], apq_i = AI[p][q];

        // phi = angle of a_pq
        double phi = d_atan2(apq_i, apq_r);
        double apq_abs = d_sqrt(apq_r*apq_r + apq_i*apq_i);

        // tau = (a_qq - a_pp) / (2 * |a_pq|)
        // theta satisfies: tan(2*theta) = 2*|a_pq| / (a_pp - a_qq)
        // Use atan2 to handle all quadrants correctly
        double denom = app_r - aqq_r;
        double theta = 0.5 * d_atan2(2.0 * apq_abs, denom);

        double cos_t = d_cos(theta);
        double sin_t = d_sin(theta);
        double cos_p = d_cos(phi);
        double sin_p = d_sin(phi);

        // Rotation matrix U (unitary):
        // U[p,p] = c
        // U[p,q] = s * exp(-i*phi) = s*(cos_p - i*sin_p)
        // U[q,p] = -s * exp(i*phi) = -s*(cos_p + i*sin_p)
        // U[q,q] = c

        // For U^H (conjugate transpose):
        // (U^H)[p,p] = c
        // (U^H)[p,q] = conj(U[q,p]) = conj(-s*(cos_p + i*sin_p)) = -s*(cos_p - i*sin_p)
        // (U^H)[q,p] = conj(U[p,q]) = conj(s*(cos_p - i*sin_p)) = s*(cos_p + i*sin_p)
        // (U^H)[q,q] = c

        // ---- A <- U^H * A * U ------------------------------------------
        // Step 1: T = U^H * A  (only rows p and q change)
        double TR[N][N], TI[N][N];

        // Copy all rows first
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                TR[i][j] = AR[i][j];
                TI[i][j] = AI[i][j];
            }
        }

        // Row p: T[p,j] = c * A[p,j] + (-s*(cos_p - i*sin_p)) * A[q,j]
        //                = c * A[p,j] - s*exp(-i*phi) * A[q,j]
        // Actually (U^H)[p,*] = [0...c...(-s*exp(-i*phi))...0]
        // where c is at column p and -s*exp(-i*phi) is at column q
        for (int j = 0; j < N; j++) {
            double ar_p = AR[p][j], ai_p = AI[p][j];
            double ar_q = AR[q][j], ai_q = AI[q][j];
            // T[p,j] = c * A[p,j] + (-s*(cos_p - i*sin_p)) * A[q,j]
            double fac_r = -sin_t * cos_p;
            double fac_i =  sin_t * sin_p;
            TR[p][j] = cos_t * ar_p + fac_r * ar_q - fac_i * ai_q;
            TI[p][j] = cos_t * ai_p + fac_r * ai_q + fac_i * ar_q;
            // T[q,j] = s*(cos_p + i*sin_p) * A[p,j] + c * A[q,j]
            double gac_r = sin_t * cos_p;
            double gac_i = sin_t * sin_p;
            TR[q][j] = gac_r * ar_p - gac_i * ai_p + cos_t * ar_q;
            TI[q][j] = gac_r * ai_p + gac_i * ar_p + cos_t * ai_q;
            local_cycles++;
        }

        // Step 2: A2 = T * U (only columns p and q change)
        double AR2[N][N], AI2[N][N];
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                AR2[i][j] = TR[i][j];
                AI2[i][j] = TI[i][j];
            }
        }

        // Col p: A2[i,p] = T[i,p] * c + T[i,q] * (-s*exp(i*phi))
        //                 = T[i,p] * c - T[i,q] * s*(cos_p + i*sin_p)
        // U[p,p] = c, U[q,p] = -s*exp(i*phi) = -s*(cos_p + i*sin_p)
        for (int i = 0; i < N; i++) {
            double tr_p = TR[i][p], ti_p = TI[i][p];
            double tr_q = TR[i][q], ti_q = TI[i][q];
            // col p: * U[p,p]=c, U[q,p]=-s*(cos_p+i*sin_p)
            double hac_r = -sin_t * cos_p;
            double hac_i = -sin_t * sin_p;
            AR2[i][p] = cos_t * tr_p + hac_r * tr_q - hac_i * ti_q;
            AI2[i][p] = cos_t * ti_p + hac_r * ti_q + hac_i * tr_q;
            // col q: U[p,q]=s*(cos_p-i*sin_p), U[q,q]=c
            double kac_r = sin_t * cos_p;
            double kac_i = -sin_t * sin_p;
            AR2[i][q] = kac_r * tr_p - kac_i * ti_p + cos_t * tr_q;
            AI2[i][q] = kac_r * ti_p + kac_i * tr_p + cos_t * ti_q;
            local_cycles++;
        }

        // Enforce exact zero and Hermitian symmetry at (p,q) and (q,p)
        AR2[p][q] = 0.0; AI2[p][q] = 0.0;
        AR2[q][p] = 0.0; AI2[q][p] = 0.0;
        // Diagonal must remain real
        AI2[p][p] = 0.0;
        AI2[q][q] = 0.0;

        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                AR[i][j] = AR2[i][j];
                AI[i][j] = AI2[i][j];
            }
        }

        // ---- V <- V * U ------------------------------------------------
        // Only columns p and q of V change
        // V2[i,p] = V[i,p]*c + V[i,q]*(-s*exp(i*phi))
        // V2[i,q] = V[i,p]*s*exp(-i*phi) + V[i,q]*c
        V_COL: for (int i = 0; i < N; i++) {
            double vr_p = VR[i][p], vi_p = VI[i][p];
            double vr_q = VR[i][q], vi_q = VI[i][q];
            // new col p: V[i,p]*c + V[i,q]*(-s*(cos_p + i*sin_p))
            double mp_r = -sin_t * cos_p;
            double mp_i = -sin_t * sin_p;
            double new_vr_p = cos_t * vr_p + mp_r * vr_q - mp_i * vi_q;
            double new_vi_p = cos_t * vi_p + mp_r * vi_q + mp_i * vr_q;
            // new col q: V[i,p]*s*(cos_p - i*sin_p) + V[i,q]*c
            double mq_r = sin_t * cos_p;
            double mq_i = -sin_t * sin_p;
            double new_vr_q = mq_r * vr_p - mq_i * vi_p + cos_t * vr_q;
            double new_vi_q = mq_r * vi_p + mq_i * vr_p + cos_t * vi_q;
            VR[i][p] = new_vr_p; VI[i][p] = new_vi_p;
            VR[i][q] = new_vr_q; VI[i][q] = new_vi_q;
            local_cycles++;
        }

    } // end JACOBI_OUTER

    clock_cycles = local_cycles;

    // ------------------------------------------------------------------
    // Pack outputs
    // ------------------------------------------------------------------
    OUT_EVAL: for (int i = 0; i < N; i++) {
        eigenvalues_re[i] = (eval_t)AR[i][i];
        eigenvalues_im[i] = (eval_t)AI[i][i];
    }
    OUT_EVEC: for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            eigenvectors_re[i][j] = (evec_t)VR[i][j];
            eigenvectors_im[i][j] = (evec_t)VI[i][j];
        }
    }
    ite = (iter_t)last_z;
}
